theorem hcomm_cons_left {l₁ l₂ : List (X → X)} {f : X → X}
    (h : ∀ f' ∈ f :: l₁, ∀ g ∈ l₂, ∀ x, f' (g x) = g (f' x)) :
    ∀ f' ∈ l₁, ∀ g ∈ l₂, ∀ x, f' (g x) = g (f' x)

theorem hcomm_cons_right {l₁ l₂ : List (X → X)} {g : X → X}
    (h : ∀ f' ∈ l₁, ∀ g' ∈ g :: l₂, ∀ x, f' (g' x) = g' (f' x)) :
    ∀ f' ∈ l₁, ∀ g' ∈ l₂, ∀ x, f' (g' x) = g' (f' x)

theorem commute_with_list_via {l₁ l₂ : List (X → X)} {g : X → X}
    (h : ∀ f' ∈ l₁, ∀ g' ∈ g :: l₂, ∀ x, f' (g' x) = g' (f' x)) :
    ∀ x, g (run l₁ x) = run l₁ (g x)

theorem commute_of_commute_fn {α : Type*} {ρ : α → Effect}
    (h : ∀ a b : α, Commute (ρ a) (ρ b)) (l₁ l₂ : List α)
    (hperm : l₁.Perm l₂) : (l₁.map ρ).prod = (l₂.map ρ).prod

theorem monotone_commute_preserved {f g : Effect}
    (hf : MonotoneEffect f) (hg : MonotoneEffect g) (h : Commute f g) :
    MonotoneEffect (f ∘ g) ∧ MonotoneEffect (g ∘ f) ∧ f ∘ g = g ∘ f
